{"task": "Find all log messages that contain an error code matching the pattern E followed by digits-dash-digits", "sql": "SELECT * FROM logs WHERE regexp_like(message, 'E[0-9]+-[0-9]+')"}
{"task": "Count how many log entries per service contain a valid error code", "sql": "SELECT service, COUNT(*) AS error_count FROM logs WHERE regexp_like(message, 'E[0-9]{3}-[0-9]{3}') GROUP BY service"}
{"task": "List distinct error codes extracted via a case-insensitive match from log messages", "sql": "SELECT DISTINCT regexp_match(message, 'E[0-9]{3}-[0-9]{3}') AS error_code FROM logs WHERE regexp_like(message, 'E[0-9]{3}-[0-9]{3}', 'i')"}
{"task": "Find error-level logs that mention an error code but exclude known benign codes like E000-000", "sql": "SELECT ts, service, message FROM logs WHERE level = 'ERROR' AND regexp_like(message, 'E[0-9]{3}-[0-9]{3}') AND NOT regexp_like(message, 'E000-000')"}
{"task": "Flag each log row with a boolean indicating whether it contains a structured error code", "sql": "SELECT ts, service, message, CASE WHEN regexp_like(message, 'E[0-9]{3}-[0-9]{3}') THEN true ELSE false END AS has_error_code FROM logs"}
{"task": "Find the most recent occurrences of a specific error code E123-456 across all services", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, 'E123-456') ORDER BY ts DESC LIMIT 50"}
{"task": "Identify services that never emit any structured error code in their messages", "sql": "SELECT service FROM logs GROUP BY service HAVING COUNT(*) FILTER (WHERE regexp_like(message, 'E[0-9]{3}-[0-9]{3}')) = 0"}
{"task": "Join events and logs to find HTTP requests whose timestamps correlate with error-code log messages from the same service", "sql": "SELECT e.id, e.path, e.status, l.message FROM events e JOIN logs l ON regexp_like(l.message, 'E[0-9]{3}-[0-9]{3}') AND l.ts BETWEEN e.id - 1000 AND e.id + 1000"}
{"task": "Categorize error codes into severity buckets based on the numeric prefix pattern in the message", "sql": "SELECT message, CASE WHEN regexp_like(message, 'E1[0-9]{2}-[0-9]{3}') THEN 'critical' WHEN regexp_like(message, 'E2[0-9]{2}-[0-9]{3}') THEN 'warning' ELSE 'other' END AS severity_bucket FROM logs WHERE regexp_like(message, 'E[0-9]{3}-[0-9]{3}')"}
{"task": "Find request paths containing an error code reference in their query string parameters", "sql": "SELECT path, status FROM events WHERE regexp_like(path, 'errorCode=E[0-9]{3}-[0-9]{3}')"}

